if parsed.path == "/api/worlds/pds-search":
    q = parse_qs(parsed.query)
    keywords = (q.get("keywords") or [""])[0][:180].strip()
    limit = max(1, min(25, int((q.get("limit") or ["12"])[0])))
    if not keywords:
        return self._json(400, {"error": "Provide a keyword or mission name."})
    params = urlencode({"keywords": keywords, "limit": limit})
    req = urllib.request.Request(
        f"{PDS_SEARCH}?{params}",
        headers={"Accept": "application/json", "User-Agent": "SWELL-Worlds/1.0"}
    )
    try:
        with urllib.request.urlopen(req, timeout=25) as response:
            raw = json.loads(response.read().decode("utf-8"))
        # PDS Search responses use a JSON-LD style envelope. Preserve the source
        # records while normalizing the common result collection shapes.
        results = raw.get("data") or raw.get("results") or raw.get("products") or []
        if isinstance(results, dict):
            results = results.get("results") or results.get("items") or []
        total = raw.get("hits") or raw.get("total") or raw.get("summary", {}).get("total")
        self._json(200, {"source": "NASA PDS Search API", "query": keywords,
                         "total": total, "results": results[:limit], "raw_keys": list(raw.keys())})
    except urllib.error.HTTPError as exc:
        detail = exc.read(1000).decode("utf-8", "replace")
        self._json(502, {"error": f"PDS API returned HTTP {exc.code}", "detail": detail})
    except Exception as exc:
        self._json(502, {"error": f"Could not reach or parse NASA PDS Search API: {exc}"})
    return

